-- aps_scenarios
select set_config('kafaa.seeding', 'on', true);
insert into kafaa_aps_scenarios (id, code, theme, title_en, title_ar, summary_en, summary_ar, context_en, context_ar, core_skill_ids, skill_ids, difficulty, est_minutes, stages, sources, status, version, sort, updated_by, updated_at) values
('aps-dt-001', 'APS-DT-001', 'digital_tool_outage', 'The work-management system goes down', 'تعطل نظام إدارة العمل', 'The electronic work-management tool fails during morning planning; then an AI assistant offers a ready-made schedule.', 'تتعطل أداة إدارة العمل الإلكترونية أثناء تخطيط الصباح، ثم يقترح مساعد ذكاء اصطناعي جدولاً جاهزاً.', 'You prepare the daily plan for a small maintenance team (non-safety buildings and workshops). The plan normally comes from the electronic work-management system. The situation is synthetic.', 'تُعدّ الخطة اليومية لفريق صيانة صغير (مبانٍ وورش غير مرتبطة بالسلامة). تأتي الخطة عادة من نظام إدارة العمل الإلكتروني. الموقف افتراضي.', array['cs-digital-judgement','cs-adaptability']::text[], array['sk-fs-ai-verify','sk-fs-tr-resilience']::text[], 2, 10, '[{"id":"plan","kind":"initial","info_en":"06:45. The team meets at 07:15. You have yesterday''s printed plan and access to the system.","info_ar":"06:45. يجتمع الفريق الساعة 07:15. لديك خطة الأمس المطبوعة وإمكانية الدخول إلى النظام.","question_en":"What do you do first?","question_ar":"ما أول ما تفعله؟","options":[{"en":"Export today''s plan and open work orders now, so a copy exists if the system has problems.","ar":"أصدّر خطة اليوم وأوامر العمل المفتوحة الآن لتتوفر نسخة إذا واجه النظام مشكلات.","eff":3,"note_en":"A minute of preparation removes a single point of failure.","note_ar":"دقيقة من التحضير تزيل نقطة الإخفاق الوحيدة."},{"en":"Plan directly from yesterday''s printout.","ar":"أخطط مباشرة من مطبوعة الأمس.","eff":1,"note_en":"Misses everything that changed overnight.","note_ar":"يفوته كل ما تغيّر خلال الليل."},{"en":"Wait until the meeting to open the system.","ar":"أنتظر حتى الاجتماع لأفتح النظام.","eff":1,"note_en":"Leaves no time to react if something is wrong.","note_ar":"لا يترك وقتاً للتصرف إذا كان هناك خلل."}],"cues":[{"en":"The plan normally comes only from the system.","ar":"تأتي الخطة عادة من النظام فقط.","relevant":true},{"en":"Yesterday''s printout is out of date.","ar":"مطبوعة الأمس قديمة.","relevant":true},{"en":"The meeting room was repainted.","ar":"أُعيد طلاء غرفة الاجتماعات.","relevant":false}],"debrief_en":"Notice single points of failure and keep a fallback copy of what the day depends on.","debrief_ar":"لاحظ نقاط الإخفاق الوحيدة واحتفظ بنسخة احتياطية مما يعتمد عليه اليوم."},{"id":"down","kind":"change","info_en":"07:05. The system is down; IT expects two hours. You exported the plan at 06:50, but two urgent work orders were raised overnight after the export.","info_ar":"07:05. النظام متعطل، ويتوقع قسم تقنية المعلومات ساعتين. صدّرت الخطة الساعة 06:50، لكن أمري عمل عاجلين أُنشئا خلال الليل بعد التصدير.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Run the meeting from the export, phone the shift desk for the two urgent orders, and record any work done on paper for later entry.","ar":"أدير الاجتماع من النسخة المصدّرة، وأتصل بمكتب النوبة لمعرفة الأمرين العاجلين، وأسجل أي عمل منجز ورقياً لإدخاله لاحقاً.","eff":3,"note_en":"Uses the fallback, closes the gap it has, and keeps records complete.","note_ar":"يستخدم البديل ويسد ثغرته ويحافظ على اكتمال السجلات."},{"en":"Cancel the meeting until the system is back.","ar":"ألغي الاجتماع حتى يعود النظام.","eff":0,"note_en":"Two idle hours and the urgent orders wait.","note_ar":"ساعتان من التعطل والأوامر العاجلة تنتظر.","keep":true},{"en":"Use the export as it is.","ar":"أستخدم النسخة المصدّرة كما هي.","eff":1,"note_en":"Misses the two urgent orders raised after the export.","note_ar":"يفوته الأمران العاجلان اللذان أُنشئا بعد التصدير."},{"en":"Let everyone pick jobs they remember.","ar":"أترك كل واحد يختار الأعمال التي يتذكرها.","eff":0,"note_en":"No plan and no record.","note_ar":"لا خطة ولا سجل."}],"cues":[{"en":"Two urgent orders came in after the export.","ar":"وصل أمران عاجلان بعد التصدير.","relevant":true},{"en":"The system should be back in about two hours.","ar":"يُتوقع عودة النظام خلال ساعتين تقريباً.","relevant":true},{"en":"IT is located in another building.","ar":"قسم تقنية المعلومات في مبنى آخر.","relevant":false},{"en":"The export was printed in colour.","ar":"طُبعت النسخة المصدّرة بالألوان.","relevant":false}],"debrief_en":"A fallback has gaps; find them and close them, and keep the record so the system can be updated later.","debrief_ar":"للبديل ثغرات؛ اكتشفها وسدّها، واحتفظ بالسجل لتحديث النظام لاحقاً."},{"id":"ai","kind":"change","info_en":"07:40. A colleague pastes the export into an approved AI assistant, which returns a neat schedule that drops one of the urgent orders and assigns a job to someone on leave.","info_ar":"07:40. يلصق زميل النسخة المصدّرة في مساعد ذكاء اصطناعي معتمد، فيعيد جدولاً مرتباً يُسقط أحد الأمرين العاجلين ويُسند عملاً إلى شخص في إجازة.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Use the AI schedule; it is tidier than yours.","ar":"أستخدم جدول الذكاء الاصطناعي فهو أكثر ترتيباً من جدولي.","eff":0,"note_en":"Tidy is not correct: it drops urgent work and uses absent staff.","note_ar":"الترتيب ليس صحة: فهو يُسقط عملاً عاجلاً ويستخدم موظفاً غائباً."},{"en":"Keep your plan, and check the AI schedule against the urgent orders and the attendance list before using any part of it.","ar":"أُبقي خطتي، وأتحقق من جدول الذكاء الاصطناعي مقارنة بالأوامر العاجلة وقائمة الحضور قبل استخدام أي جزء منه.","eff":3,"note_en":"The AI output is a draft to verify, not a decision; two errors are already visible.","note_ar":"مخرجات الذكاء الاصطناعي مسودة للتحقق وليست قراراً؛ وهناك خطآن ظاهران بالفعل.","keep":true},{"en":"Forbid the colleague from using AI tools.","ar":"أمنع الزميل من استخدام أدوات الذكاء الاصطناعي.","eff":1,"note_en":"The tool is approved; the issue is verification, not use.","note_ar":"الأداة معتمدة؛ والمشكلة في التحقق لا في الاستخدام."},{"en":"Fix the two errors and adopt the AI schedule without further checks.","ar":"أصحح الخطأين وأعتمد جدول الذكاء الاصطناعي دون فحوص أخرى.","eff":2,"note_en":"Better, but where there are two errors, check for more.","note_ar":"أفضل، لكن حيث يوجد خطآن ابحث عن المزيد."}],"cues":[{"en":"The AI schedule drops one urgent order.","ar":"جدول الذكاء الاصطناعي يُسقط أمراً عاجلاً.","relevant":true},{"en":"It assigns a job to someone on leave.","ar":"يُسند عملاً إلى شخص في إجازة.","relevant":true},{"en":"The AI assistant is on the approved list.","ar":"مساعد الذكاء الاصطناعي مدرج في القائمة المعتمدة.","relevant":true},{"en":"The colleague types faster than you.","ar":"يكتب الزميل أسرع منك.","relevant":false}],"debrief_en":"An approved tool can still be wrong. Verify AI output against the facts you hold before it replaces your plan.","debrief_ar":"الأداة المعتمدة قد تخطئ أيضاً. تحقق من مخرجات الذكاء الاصطناعي مقارنة بالحقائق التي لديك قبل أن تحل محل خطتك."}]'::jsonb, '[{"label":"OECD Survey of Adult Skills (PIAAC), Cycle 2 database: adaptive problem solving","url":"https://www.oecd.org/en/data/datasets/PIAAC-2nd-Cycle-Database.html","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"CSO Ireland · PIAAC 2023 key findings (publishes the OECD averages)","url":"https://www.cso.ie/en/releasesandpublications/ep/p-piaac/programmefortheinternationalassessmentofadultcompetenciespiaac2023/keyfindings","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', 1, 6, 'p-training-mgr', '2026-09-28T09:00:00Z'),
('aps-wl-001', 'APS-WL-001', 'weather_logistics', 'Sandstorm on contractor arrival day', 'عاصفة رملية في يوم وصول المقاولين', 'Draft: a contractor team is due on site when a sandstorm warning is issued; then the road reopens early.', 'مسودة: فريق مقاول يُنتظر وصوله إلى الموقع حين يصدر تحذير من عاصفة رملية، ثم يُعاد فتح الطريق مبكراً.', 'You host a contractor team arriving by bus for a week of scaffolding work in a non-safety area. The situation is synthetic.', 'تستضيف فريق مقاول يصل بالحافلة لأسبوع من أعمال السقالات في منطقة غير مرتبطة بالسلامة. الموقف افتراضي.', array['cs-adaptability','cs-systems']::text[], array['sk-fs-tr-systems','sk-fs-tr-resilience']::text[], 2, 10, '[{"id":"plan","kind":"initial","info_en":"The bus arrives at 08:00; site induction is at 09:00; work starts at 11:00.","info_ar":"تصل الحافلة الساعة 08:00، والتعريف بالموقع الساعة 09:00، ويبدأ العمل الساعة 11:00.","question_en":"What do you do first?","question_ar":"ما أول ما تفعله؟","options":[{"en":"Confirm the induction room, the escort and a call tree in case of travel problems.","ar":"أؤكد قاعة التعريف والمرافق وسلسلة اتصال تحسباً لمشكلات السفر.","eff":3,"note_en":"Cheap preparation for the likely failure.","note_ar":"تحضير قليل الكلفة للإخفاق المحتمل."},{"en":"Nothing extra.","ar":"لا شيء إضافي.","eff":1,"note_en":"No plan B for travel.","note_ar":"لا خطة بديلة للسفر."},{"en":"Start work at 08:00 without induction.","ar":"أبدأ العمل الساعة 08:00 دون تعريف.","eff":0,"note_en":"Induction is not optional.","note_ar":"التعريف ليس اختيارياً."}],"cues":[{"en":"Everyone arrives on one bus.","ar":"يصل الجميع في حافلة واحدة.","relevant":true},{"en":"Induction comes before work.","ar":"التعريف يسبق العمل.","relevant":true},{"en":"The bus is blue.","ar":"الحافلة زرقاء.","relevant":false}],"debrief_en":"Prepare for the obvious single point of failure.","debrief_ar":"استعد لنقطة الإخفاق الوحيدة الواضحة."},{"id":"storm","kind":"change","info_en":"07:00. A sandstorm warning closes the access road until 12:00.","info_ar":"07:00. يُغلق تحذير من عاصفة رملية طريق الوصول حتى الساعة 12:00.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Hold the bus at the hotel, move induction to 13:00 and work to the next day.","ar":"أُبقي الحافلة في الفندق، وأنقل التعريف إلى 13:00 والعمل إلى اليوم التالي.","eff":3,"note_en":"Safe and realistic re-plan.","note_ar":"إعادة تخطيط آمنة وواقعية."},{"en":"Keep the plan; the bus will find a way.","ar":"أُبقي الخطة؛ ستجد الحافلة طريقاً.","eff":0,"note_en":"Unsafe travel.","note_ar":"سفر غير آمن.","keep":true},{"en":"Cancel the week.","ar":"ألغي الأسبوع.","eff":1,"note_en":"Too much for a half-day delay.","note_ar":"أكثر من اللازم لتأخير نصف يوم."}],"cues":[{"en":"The road is closed until 12:00.","ar":"الطريق مغلق حتى 12:00.","relevant":true},{"en":"The team is still at the hotel.","ar":"ما زال الفريق في الفندق.","relevant":true},{"en":"The forecast was issued by e-mail.","ar":"صدر التحذير بالبريد الإلكتروني.","relevant":false}],"debrief_en":"Move the plan around the new constraint, not through it.","debrief_ar":"حرّك الخطة حول القيد الجديد لا عبره."}]'::jsonb, '[{"label":"OECD Survey of Adult Skills (PIAAC), Cycle 2 database: adaptive problem solving","url":"https://www.oecd.org/en/data/datasets/PIAAC-2nd-Cycle-Database.html","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"CSO Ireland · PIAAC 2023 key findings (publishes the OECD averages)","url":"https://www.cso.ie/en/releasesandpublications/ep/p-piaac/programmefortheinternationalassessmentofadultcompetenciespiaac2023/keyfindings","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'draft', 1, 7, 'p-training-mgr', '2026-09-28T09:00:00Z')
on conflict (id) do nothing;

